CREATE   VIEW [RegsBI].[vwSystemUser_CE]
AS
SELECT 
	[systemuserid]
	,[domainname]
	,[title]
	,[salutation]
	,[internalemailaddress]
	,[positionid]
	,[parentsystemuserid]
	,[lastname]
	,[jobtitle]
	,[fullname]
	,[firstname]
	,[apitil_department]
	,[address1_country]
	,[address1_city]
	,[businessunitid]
	,[businessunit_name]
FROM [synapse_ce].[vwSystemUser]
